        "tipEn": "Key Thematic Essence: Malicious Wit, Irony of Greed, Psychological Torment, The Dilemma of Wealth",
        "tipTa": "பாடத்தின் மையக்கருத்து: Malicious Wit, Irony of Greed, Psychological Torment, The Dilemma of Wealth"
