    "descriptionTa": "உரைநடை: பேய் நுழைந்த அந்த இரவு (ஜேம்ஸ் தர்பர்) பாடத்தின் முக்கிய கருப்பொருள்களை விளக்கும் வரைபடம்.",
    "diagramType": "svg_labeled",
