        "descriptionEn": "Grandfather's historic delusion resulting in friendly fire.",
        "descriptionTa": "தாத்தாவின் போர் நினைவுகளால் நிகழ்ந்த துப்பாக்கிச் சூடு.",
        "x": 80,
