    "descriptionTa": "உரைநடை: உலகை வலம் வந்த வீர மங்கையர் (ஐ.என்.எஸ்.வி தாரிணி) பாடத்தின் முக்கிய கருப்பொருள்களை விளக்கும் வரைபடம்.",
    "diagramType": "svg_labeled",
