    "titleEn": "Concept Mindmap: Supplementary: A Day in 2889 of an American Journalist (Jules Verne)",
    "titleTa": "கருத்து விளக்க வரைபடம்: துணைப்பாடம்: கி.பி 2889-ல் ஒரு அமெரிக்கப் பத்திரிகையாளனின் நாள் (ஜூல்ஸ் வெர்ன்)",
    "descriptionEn": "Interactive structural diagram of Supplementary: A Day in 2889 of an American Journalist (Jules Verne) detailing thematic progression.",
    "descriptionTa": "துணைப்பாடம்: கி.பி 2889-ல் ஒரு அமெரிக்கப் பத்திரிகையாளனின் நாள் (ஜூல்ஸ் வெர்ன்) பாடத்தின் முக்கிய கருப்பொருள்களை விளக்கும் வரைபடம்.",
    "diagramType": "svg_labeled",
    "svgContent": "<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" className=\"w-full h-auto rounded-xl shadow-lg border border-slate-700 bg-slate-900\">\n  <defs>\n    <linearGradient id=\"grad_c10_eng_u5_s1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stopColor=\"#1e3a8a\" stopOpacity=\"0.8\" />\n      <stop offset=\"100%\" stopColor=\"#0f172a\" stopOpacity=\"0.9\" />\n    </linearGradient>\n    <filter id=\"glow_c10_eng_u5_s1\">\n      <feGaussianBlur stdDeviation=\"3\" result=\"coloredBlur\"/>\n      <feMerge>\n        <feMergeNode in=\"coloredBlur\"/>\n        <feMergeNode in=\"SourceGraphic\"/>\n      </feMerge>\n    </filter>\n  </defs>\n\n  <rect width=\"800\" height=\"450\" fill=\"url(#grad_c10_eng_u5_s1)\" rx=\"12\" />\n  <rect x=\"20\" y=\"20\" width=\"760\" height=\"60\" rx=\"8\" fill=\"#1e293b\" stroke=\"#3b82f6\" strokeWidth=\"1.5\" />\n  <text x=\"400\" y=\"45\" fill=\"#60a5fa\" fontSize=\"16\" fontWeight=\"bold\" textAnchor=\"middle\" letterSpacing=\"1\">UNIT 5: TECHNOLOGY, MACHINES & FUTURE</text>\n  <text x=\"400\" y=\"68\" fill=\"#f8fafc\" fontSize=\"18\" fontWeight=\"bold\" textAnchor=\"middle\">Supplementary: A Day in 2889 of an American Journalist (Jules Verne)</text>\n\n  <!-- Flow connecting arrows -->\n  <path d=\"M 230 225 L 370 225\" stroke=\"#60a5fa\" strokeWidth=\"2.5\" strokeDasharray=\"5,5\" />\n  <polygon points=\"370,221 380,225 370,229\" fill=\"#60a5fa\" />\n  <path d=\"M 430 225 L 570 225\" stroke=\"#38bdf8\" strokeWidth=\"2.5\" strokeDasharray=\"5,5\" />\n  <polygon points=\"570,221 580,225 570,229\" fill=\"#38bdf8\" />\n\n  <!-- Node 1 -->\n  <g transform=\"translate(100, 150)\" filter=\"url(#glow_c10_eng_u5_s1)\">\n    <rect width=\"130\" height=\"150\" rx=\"10\" fill=\"#0f172a\" stroke=\"#3b82f6\" strokeWidth=\"2\" />\n    <circle cx=\"65\" cy=\"45\" r=\"24\" fill=\"#1e3a8a\" stroke=\"#60a5fa\" strokeWidth=\"2\" />\n    <text x=\"65\" y=\"52\" fill=\"#93c5fd\" fontSize=\"16\" fontWeight=\"bold\" textAnchor=\"middle\">1</text>\n    <text x=\"65\" y=\"95\" fill=\"#e2e8f0\" fontSize=\"12\" fontWeight=\"bold\" textAnchor=\"middle\">Phonotelephote (</text>\n    <text x=\"65\" y=\"112\" fill=\"#94a3b8\" fontSize=\"10\" textAnchor=\"middle\">Modern Videocall</text>\n    <rect x=\"25\" y=\"125\" width=\"80\" height=\"16\" rx=\"4\" fill=\"#1e293b\" />\n    <text x=\"65\" y=\"137\" fill=\"#38bdf8\" fontSize=\"9\" fontWeight=\"bold\" textAnchor=\"middle\">PHASE I</text>\n  </g>\n\n  <!-- Node 2 -->\n  <g transform=\"translate(335, 140)\" filter=\"url(#glow_c10_eng_u5_s1)\">\n    <rect width=\"130\" height=\"170\" rx=\"10\" fill=\"#0f172a\" stroke=\"#0ea5e9\" strokeWidth=\"2.5\" />\n    <circle cx=\"65\" cy=\"45\" r=\"26\" fill=\"#0369a1\" stroke=\"#38bdf8\" strokeWidth=\"2\" />\n    <text x=\"65\" y=\"52\" fill=\"#bae6fd\" fontSize=\"16\" fontWeight=\"bold\" textAnchor=\"middle\">2</text>\n    <text x=\"65\" y=\"95\" fill=\"#e2e8f0\" fontSize=\"12\" fontWeight=\"bold\" textAnchor=\"middle\">Pneumatic Tubes </text>\n    <text x=\"65\" y=\"112\" fill=\"#94a3b8\" fontSize=\"10\" textAnchor=\"middle\">& Aero-Cars</text>\n    <rect x=\"25\" y=\"135\" width=\"80\" height=\"18\" rx=\"4\" fill=\"#0284c7\" />\n    <text x=\"65\" y=\"148\" fill=\"#f8fafc\" fontSize=\"10\" fontWeight=\"bold\" textAnchor=\"middle\">CATALYST</text>\n  </g>\n\n  <!-- Node 3 -->\n  <g transform=\"translate(570, 150)\" filter=\"url(#glow_c10_eng_u5_s1)\">\n    <rect width=\"130\" height=\"150\" rx=\"10\" fill=\"#0f172a\" stroke=\"#10b981\" strokeWidth=\"2\" />\n    <circle cx=\"65\" cy=\"45\" r=\"24\" fill=\"#065f46\" stroke=\"#34d399\" strokeWidth=\"2\" />\n    <text x=\"65\" y=\"52\" fill=\"#a7f3d0\" fontSize=\"16\" fontWeight=\"bold\" textAnchor=\"middle\">3</text>\n    <text x=\"65\" y=\"95\" fill=\"#e2e8f0\" fontSize=\"12\" fontWeight=\"bold\" textAnchor=\"middle\">Interplanetary M</text>\n    <text x=\"65\" y=\"112\" fill=\"#94a3b8\" fontSize=\"10\" textAnchor=\"middle\">edia Empire</text>\n    <rect x=\"25\" y=\"125\" width=\"80\" height=\"16\" rx=\"4\" fill=\"#1e293b\" />\n    <text x=\"65\" y=\"137\" fill=\"#34d399\" fontSize=\"9\" fontWeight=\"bold\" textAnchor=\"middle\">TRIUMPH</text>\n  </g>\n\n  <!-- Footer Tag -->\n  <rect x=\"200\" y=\"380\" width=\"400\" height=\"40\" rx=\"20\" fill=\"#1e293b\" stroke=\"#475569\" strokeWidth=\"1\" />\n  <text x=\"400\" y=\"405\" fill=\"#cbd5e1\" fontSize=\"12\" fontWeight=\"bold\" textAnchor=\"middle\">EduVoice Visual Learning Schematic • Samacheer Kalvi Class 10</text>\n</svg>",
