        "narrationTa": "எச்சரிக்கை! எங்களுக்கு அன்போ மன்னிப்போ கிடையாது; எங்கள் விதிகளை மதித்து இயங்குங்கள், சிறு பிழையும் பேராபத்தாகும்!",
