        "visualDescriptionEn": "City lights twinkling against the night sky, high-speed maglev trains, with a human engineer smiling at blueprint plans.",
        "narrationEn": "Though our smoke eclipses the stars and our power moves mountains, remember: we are nothing more than children of the human brain!",
